#include <stdio.h>
#include <stdlib.h>

long catalan(int n) {
    if (n == 0 || n == 1) {
        return 1;
    }

    long* catalan_numbers = (long*) malloc((n + 1) * sizeof(long));
    catalan_numbers[0] = 1;
    catalan_numbers[1] = 1;

    for (int i = 2; i <= n; i++) {
        catalan_numbers[i] = 0;
        for (int j = 0; j < i; j++) {
            catalan_numbers[i] += catalan_numbers[j] * catalan_numbers[i - j - 1];
        }
    }

    long result = catalan_numbers[n];
    free(catalan_numbers);
    return result;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("NO_INPUT\n");
        return 0;
    }

    char* endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        printf("BAD_INPUT\n");
        return 0;
    }

    if (n < 0) {
        printf("OUT_OF_RANGE\n");
        return 0;
    }

    long result = catalan(n);
    printf("%lld\n", result);
    return 0;
}
